 @LocalServerPort int port;@Autowired JdbcTemplate jdbc;@Autowired PasswordEncoder passwords;@Autowired JsonMapper json;@Autowired MfaSecrets secrets;@Autowired com.printflow.whatsapp.WhatsappEncryption whatsappEncryption;@Autowired com.printflow.whatsapp.WhatsappService whatsapp;@Autowired com.printflow.whatsapp.WhatsappOutboxWorker whatsappOutbox;@Autowired com.printflow.files.ArtifactStorage artifactStore;@Autowired CustomerMail mail;
