 @Test void onlyOwnerAndDesignerSeeUnacceptedIntake()throws Exception{UUID id=lead("NEW");assertFalse(seller.send("GET","/api/v1/staff/enquiries",null,false).body().contains(id.toString()));assertEquals(404,seller.send("GET","/api/v1/staff/enquiries/"+id+"/quotes",null,false).statusCode());assertEquals(404,seller.send("GET","/api/v1/design/enquiries/"+id+"/work",null,false).statusCode());assertEquals(403,seller.send("GET","/api/v1/design/intake",null,false).statusCode());assertEquals(403,seller.send("POST","/api/v1/design/intake/"+id+"/accept","{\"revision\":0}",true).statusCode());var intake=artist.send("GET","/api/v1/design/intake",null,false);assertEquals(200,intake.statusCode());assertTrue(intake.body().contains(id.toString()));assertFalse(intake.body().contains("scope@example.test"));assertFalse(intake.body().contains("assigned_staff_id"));assertEquals(404,artist.send("GET","/api/v1/design/enquiries/"+id,null,false).statusCode());assertEquals(200,artist.send("POST","/api/v1/design/intake/"+id+"/accept","{\"revision\":0}",true).statusCode());assertEquals(409,artist.send("POST","/api/v1/design/intake/"+id+"/accept","{\"revision\":0}",true).statusCode());assertEquals(designer,jdbc.queryForObject("select designer_id from enquiries where id=?",UUID.class,id));assertEquals(200,artist.send("GET","/api/v1/design/enquiries/"+id,null,false).statusCode());assertTrue(seller.send("GET","/api/v1/staff/enquiries",null,false).body().contains(id.toString()));UUID rejected=lead("NEW");assertEquals(200,artist.send("POST","/api/v1/design/intake/"+rejected+"/reject","{\"revision\":0,\"comment\":\"Requested stock is unavailable\"}",true).statusCode());assertEquals("REJECTED",jdbc.queryForObject("select closure_kind from enquiries where id=?",String.class,rejected));}
