 @Test void whatsappInboxIsLimitedToOwnerAndSalesAndHandoffCanBeClaimed()throws Exception{UUID conversation=UUID.randomUUID();String phone="919000000123",phoneHash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(phone.getBytes(StandardCharsets.UTF_8)));try{jdbc.update("insert into whatsapp_conversations(id,phone_hash,phone_ciphertext,contact_name_ciphertext,handoff_status) values(?,?,?,?, 'HUMAN')",conversation,phoneHash,whatsappEncryption.encrypt("+"+phone),whatsappEncryption.encrypt("Synthetic WhatsApp contact"));assertEquals(200,boss.send("GET","/api/v1/staff/whatsapp",null,false).statusCode());var visible=seller.send("GET","/api/v1/staff/whatsapp",null,false);assertEquals(200,visible.statusCode());assertTrue(visible.body().contains(conversation.toString()));assertEquals(403,artist.send("GET","/api/v1/staff/whatsapp",null,false).statusCode());assertEquals(403,press.send("GET","/api/v1/staff/whatsapp",null,false).statusCode());assertEquals(403,buyer.send("GET","/api/v1/staff/whatsapp",null,false).statusCode());var claimed=seller.send("POST","/api/v1/staff/whatsapp/"+conversation+"/claim","{}",true);assertEquals(200,claimed.statusCode(),claimed.body());assertEquals(sales.toString(),json.readValue(claimed.body(),Map.class).get("assignedStaffId"));assertEquals(200,seller.send("GET","/api/v1/staff/whatsapp/"+conversation,null,false).statusCode());}finally{jdbc.update("delete from whatsapp_messages where conversation_id=?",conversation);jdbc.update("delete from whatsapp_handoff_requests where conversation_id=?",conversation);jdbc.update("delete from whatsapp_conversations where id=?",conversation);}}
 @Test void localSimulatorStoresMenuAndHumanHandoffWithoutCreatingAnEnquiry()throws Exception{String phone="919000000124",hash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(phone.getBytes(StandardCharsets.UTF_8)));UUID conversation=null;try{assertEquals(403,seller.send("POST","/api/v1/owner/whatsapp/simulate","{\"phone\":\""+phone+"\",\"text\":\"MENU\"}",true).statusCode());assertEquals(202,boss.send("POST","/api/v1/owner/whatsapp/simulate","{\"phone\":\""+phone+"\",\"text\":\"MENU\"}",true).statusCode());conversation=jdbc.queryForObject("select id from whatsapp_conversations where phone_hash=?",UUID.class,hash);assertTrue(jdbc.queryForObject("select count(*) from whatsapp_messages where conversation_id=? and direction='INBOUND'",Integer.class,conversation)>=1);assertTrue(jdbc.queryForObject("select count(*) from whatsapp_messages where conversation_id=? and direction='OUTBOUND' and delivery_status='QUEUED'",Integer.class,conversation)>=1);assertEquals("MENU",jdbc.queryForObject("select bot_state from whatsapp_conversations where id=?",String.class,conversation));assertEquals(202,boss.send("POST","/api/v1/owner/whatsapp/simulate","{\"phone\":\""+phone+"\",\"text\":\"4\"}",true).statusCode());assertEquals("HUMAN",jdbc.queryForObject("select handoff_status from whatsapp_conversations where id=?",String.class,conversation));assertEquals(1,jdbc.queryForObject("select count(*) from whatsapp_handoff_requests where conversation_id=? and status='OPEN'",Integer.class,conversation));assertEquals(0,jdbc.queryForObject("select count(*) from enquiries where source='WHATSAPP' and phone like ?",Integer.class,"%"+phone.substring(3)));}finally{if(conversation!=null){jdbc.update("delete from whatsapp_messages where conversation_id=?",conversation);jdbc.update("delete from whatsapp_handoff_requests where conversation_id=?",conversation);jdbc.update("delete from whatsapp_conversations where id=?",conversation);}}}
 @Test void quoteSubmissionIsServerIdempotentAndWhatsappConsentIsSeparate()throws Exception{String key="batch5-"+UUID.randomUUID(),email="batch5-idempotency-"+UUID.randomUUID()+"@example.test";UUID enquiry=null;try{Map<String,Object> payload=new LinkedHashMap<>();payload.put("customerName","Synthetic idempotency customer");payload.put("email",email);payload.put("phone","+919000000127");payload.put("productCode","WEDDING_CARDS");payload.put("quantity",250);payload.put("privacyConsent",true);payload.put("privacyVersion",com.printflow.identity.CustomerIdentityController.PRIVACY);payload.put("website","");payload.put("intendedUse","Synthetic two-family invitation request");payload.put("whatsappConsent",true);String body=json.writeValueAsString(payload);Client client=new Client();var first=client.sendWithHeader("POST","/api/public/enquiries",body,"Idempotency-Key",key);assertEquals(201,first.statusCode(),first.body());var original=json.readValue(first.body(),com.printflow.enquiry.EnquiryDtos.CreatedEnquiry.class);enquiry=jdbc.queryForObject("select id from enquiries where public_id=?",UUID.class,original.publicId());var replay=client.sendWithHeader("POST","/api/public/enquiries",body,"Idempotency-Key",key);assertEquals(201,replay.statusCode(),replay.body());var repeated=json.readValue(replay.body(),com.printflow.enquiry.EnquiryDtos.CreatedEnquiry.class);assertEquals(original.publicId(),repeated.publicId());assertEquals(original.trackingToken(),repeated.trackingToken());payload.put("intendedUse","Changed brief with the same key");assertEquals(409,client.sendWithHeader("POST","/api/public/enquiries",json.writeValueAsString(payload),"Idempotency-Key",key).statusCode());assertEquals(1,jdbc.queryForObject("select count(*) from enquiries where public_id=?",Integer.class,original.publicId()));assertEquals("Synthetic two-family invitation request",jdbc.queryForObject("select intended_use from enquiries where id=?",String.class,enquiry));assertEquals(1,jdbc.queryForObject("select count(*) from whatsapp_contact_consents where enquiry_id=? and channel='WEBSITE' and granted=true",Integer.class,enquiry));}finally{if(enquiry==null)enquiry=jdbc.query("select id from enquiries where email=?",(rs,n)->rs.getObject(1,UUID.class),email).stream().findFirst().orElse(null);if(enquiry!=null){jdbc.update("delete from mail_outbox where enquiry_id=?",enquiry);jdbc.update("delete from whatsapp_contact_consents where enquiry_id=?",enquiry);jdbc.update("delete from enquiry_events where enquiry_id=?",enquiry);jdbc.update("delete from enquiry_request_idempotency where key_hash=?",com.printflow.enquiry.TokenUtil.sha256(key));jdbc.update("delete from enquiries where id=?",enquiry);}}}
 @Test void whatsappWebhookVerifiesSignaturesDeduplicatesAndKeepsStatusesMonotonic()throws Exception{String phone="919000000126",providerId="wamid.batch5."+UUID.randomUUID(),contactHash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(phone.getBytes(StandardCharsets.UTF_8)));UUID conversation=null,outbound=UUID.randomUUID();try{Client client=new Client();var verify=client.client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/public/whatsapp/webhook?hub.mode=subscribe&hub.verify_token=synthetic-whatsapp-verify-token-batch5-123456&hub.challenge=sample-challenge")).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,verify.statusCode());assertEquals("sample-challenge",verify.body());var invalid=client.client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/public/whatsapp/webhook?hub.mode=subscribe&hub.verify_token=wrong&hub.challenge=sample-challenge")).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(403,invalid.statusCode());long now=Instant.now().getEpochSecond();String body=json.writeValueAsString(Map.of("entry",List.of(Map.of("changes",List.of(Map.of("value",Map.of("messages",List.of(Map.of("id",providerId,"from",phone,"timestamp",Long.toString(now),"type","text","text",Map.of("body","MENU"))),"contacts",List.of(Map.of("wa_id",phone,"profile",Map.of("name","Synthetic webhook contact"))))))))));byte[] raw=body.getBytes(StandardCharsets.UTF_8);assertEquals(401,webhook(raw,null).statusCode());assertEquals(401,webhook(raw,"sha256="+"0".repeat(64)).statusCode());assertEquals(401,webhook("tampered".getBytes(StandardCharsets.UTF_8),signature(raw)).statusCode());assertEquals(200,webhook(raw,signature(raw)).statusCode());assertEquals(200,webhook(raw,signature(raw)).statusCode());conversation=jdbc.queryForObject("select id from whatsapp_conversations where phone_hash=?",UUID.class,contactHash);assertEquals(1,jdbc.queryForObject("select count(*) from whatsapp_messages where provider_message_id=? and direction='INBOUND'",Integer.class,providerId));assertEquals(1,jdbc.queryForObject("select count(*) from whatsapp_messages where conversation_id=? and direction='OUTBOUND'",Integer.class,conversation));assertEquals("PROCESSED",jdbc.queryForObject("select state from whatsapp_events where provider_event_id=?",String.class,"message:"+providerId));byte[] oversized=new byte[262145];java.util.Arrays.fill(oversized,(byte)'x');assertEquals(413,webhook(oversized,signature(oversized)).statusCode());String outgoingId="wamid.outgoing."+UUID.randomUUID();jdbc.update("insert into whatsapp_messages(id,conversation_id,provider_message_id,idempotency_key,direction,message_type,delivery_status,provider_status_at) values(?,?,? ,?,'OUTBOUND','text','SENT',to_timestamp(?))",outbound,conversation,outgoingId,"itest:"+outgoingId,now-10);String delivered=json.writeValueAsString(Map.of("entry",List.of(Map.of("changes",List.of(Map.of("value",Map.of("statuses",List.of(Map.of("id",outgoingId,"status","delivered","timestamp",Long.toString(now))))))))));assertEquals(200,webhook(delivered.getBytes(StandardCharsets.UTF_8),signature(delivered.getBytes(StandardCharsets.UTF_8))).statusCode());String oldSent=json.writeValueAsString(Map.of("entry",List.of(Map.of("changes",List.of(Map.of("value",Map.of("statuses",List.of(Map.of("id",outgoingId,"status","sent","timestamp",Long.toString(now-5))))))))));assertEquals(200,webhook(oldSent.getBytes(StandardCharsets.UTF_8),signature(oldSent.getBytes(StandardCharsets.UTF_8))).statusCode());assertEquals("DELIVERED",jdbc.queryForObject("select delivery_status from whatsapp_messages where id=?",String.class,outbound));}finally{if(conversation!=null){jdbc.update("delete from whatsapp_messages where conversation_id=?",conversation);jdbc.update("delete from whatsapp_handoff_requests where conversation_id=?",conversation);jdbc.update("delete from whatsapp_contact_consents where conversation_id=?",conversation);jdbc.update("delete from whatsapp_events where provider_event_id like ?", "message:wamid.batch5.%");jdbc.update("delete from whatsapp_events where provider_event_id like ?", "status:wamid.outgoing.%");jdbc.update("delete from whatsapp_conversations where id=?",conversation);}jdbc.update("delete from whatsapp_messages where id=?",outbound);}}
 @Test void whatsappHumanHandoffStopsBotRepliesAndPreservesOptOutAndResume()throws Exception{
  String phone=syntheticPhone();
  String phoneHash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(phone.getBytes(StandardCharsets.UTF_8)));
  UUID conversation=null;
  try{
   var menu=webhookMessage("wamid.e1."+UUID.randomUUID(),phone,"MENU");
   assertEquals(200,webhook(menu,signature(menu)).statusCode());
   assertEquals(200,webhook(menu,signature(menu)).statusCode()); // duplicate signed delivery is idempotent
   conversation=jdbc.queryForObject("select id from whatsapp_conversations where phone_hash=?",UUID.class,phoneHash);
   assertEquals(1,countMessages(conversation,"INBOUND"));
   assertEquals(1,countMessages(conversation,"OUTBOUND"));

   assertEquals(200,webhookSignedMessage(phone,"4").statusCode());
   assertEquals("HUMAN",jdbc.queryForObject("select handoff_status from whatsapp_conversations where id=?",String.class,conversation));
   assertEquals("HANDOFF",jdbc.queryForObject("select bot_state from whatsapp_conversations where id=?",String.class,conversation));
   int afterHandoff=countMessages(conversation,"OUTBOUND");
   assertEquals(2,afterHandoff);
   assertEquals(200,seller.send("POST","/api/v1/staff/whatsapp/"+conversation+"/claim","{}",true).statusCode());
   assertEquals(403,artist.send("POST","/api/v1/staff/whatsapp/"+conversation+"/reply","{\"text\":\"Unauthorized synthetic reply\"}",true).statusCode());

   assertEquals(200,webhookSignedMessage(phone,"A person is reviewing this now").statusCode());
   assertEquals(3,countMessages(conversation,"INBOUND"));
   assertEquals(afterHandoff,countMessages(conversation,"OUTBOUND"),"Human-controlled conversations must not receive automatic bot replies");
   assertEquals(202,seller.send("POST","/api/v1/staff/whatsapp/"+conversation+"/reply","{\"text\":\"Synthetic authorized staff reply\"}",true).statusCode());
   assertEquals(3,countMessages(conversation,"OUTBOUND"));

   assertEquals(200,seller.send("POST","/api/v1/staff/whatsapp/"+conversation+"/resume","{}",true).statusCode());
   assertEquals("BOT",jdbc.queryForObject("select handoff_status from whatsapp_conversations where id=?",String.class,conversation));
   assertEquals(200,webhookSignedMessage(phone,"Hello again").statusCode());
   assertEquals(4,countMessages(conversation,"OUTBOUND"),"Bot should respond after the assigned staff member resumes it");

   assertEquals(200,webhookSignedMessage(phone,"4").statusCode());
   assertEquals(200,seller.send("POST","/api/v1/staff/whatsapp/"+conversation+"/claim","{}",true).statusCode());
   int beforeStop=countMessages(conversation,"OUTBOUND");
   assertEquals(200,webhookSignedMessage(phone,"STOP").statusCode());
   assertTrue(jdbc.queryForObject("select suppressed_at is not null from whatsapp_conversations where id=?",Boolean.class,conversation));
   assertEquals("HUMAN",jdbc.queryForObject("select handoff_status from whatsapp_conversations where id=?",String.class,conversation));
   assertEquals(beforeStop+1,countMessages(conversation,"OUTBOUND"),"STOP under human control may queue only its operational acknowledgement");
   assertEquals("OPT_OUT_ACK",jdbc.queryForObject("select message_type from whatsapp_messages where conversation_id=? and direction='OUTBOUND' order by created_at desc,id desc limit 1",String.class,conversation));
   assertEquals(409,seller.send("POST","/api/v1/staff/whatsapp/"+conversation+"/reply","{\"text\":\"Blocked after opt out\"}",true).statusCode());
  }finally{
   if(conversation!=null){jdbc.update("delete from whatsapp_messages where conversation_id=?",conversation);jdbc.update("delete from whatsapp_handoff_requests where conversation_id=?",conversation);jdbc.update("delete from whatsapp_contact_consents where conversation_id=?",conversation);jdbc.update("delete from whatsapp_events where provider_event_id like 'message:wamid.e1.%'");jdbc.update("delete from whatsapp_conversations where id=?",conversation);}
  }
 }

 @Test void whatsappOutboxMarksCrashedSendsUnknownAndAppliesEarlyProviderStatus()throws Exception{
  String phone=syntheticPhone(),providerId="wamid.e1.early."+UUID.randomUUID();
  String phoneHash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(phone.getBytes(StandardCharsets.UTF_8)));
  UUID conversation=UUID.randomUUID(),stale=UUID.randomUUID(),early=UUID.randomUUID();
  try{
   jdbc.update("insert into whatsapp_conversations(id,phone_hash,phone_ciphertext) values(?,?,?)",conversation,phoneHash,whatsappEncryption.encrypt("+"+phone));
   jdbc.update("insert into whatsapp_messages(id,conversation_id,idempotency_key,direction,message_type,delivery_status,attempts,sending_started_at) values(?,?,?,'OUTBOUND','text','SENDING',2,now()-interval '3 minutes')",stale,conversation,"e1-stale:"+stale);
   whatsappOutbox.dispatch();
   assertEquals("UNKNOWN",jdbc.queryForObject("select delivery_status from whatsapp_messages where id=?",String.class,stale));
   assertEquals(2,jdbc.queryForObject("select attempts from whatsapp_messages where id=?",Integer.class,stale));
   assertNull(jdbc.queryForObject("select next_attempt_at from whatsapp_messages where id=?",java.sql.Timestamp.class,stale));

   jdbc.update("insert into whatsapp_messages(id,conversation_id,idempotency_key,direction,message_type,delivery_status,attempts,sending_started_at) values(?,?,?,'OUTBOUND','text','SENDING',1,now())",early,conversation,"e1-early:"+early);
   assertEquals(200,webhookSignedStatus(providerId,"delivered").statusCode());
   assertNull(jdbc.queryForObject("select applied_at from whatsapp_provider_status_events where provider_message_id=?",java.sql.Timestamp.class,providerId));
   whatsapp.recordProviderAccepted(early,providerId);
   assertEquals("DELIVERED",jdbc.queryForObject("select delivery_status from whatsapp_messages where id=?",String.class,early));
   assertNotNull(jdbc.queryForObject("select applied_at from whatsapp_provider_status_events where provider_message_id=?",java.sql.Timestamp.class,providerId));
   assertEquals(0,jdbc.queryForObject("select count(*) from whatsapp_messages where id=? and delivery_status='QUEUED'",Integer.class,stale));
  }finally{
   jdbc.update("delete from whatsapp_provider_status_events where provider_message_id=?",providerId);
   jdbc.update("delete from whatsapp_messages where id in (?,?)",stale,early);
   jdbc.update("delete from whatsapp_conversations where id=?",conversation);
  }
 }

 @Test void syntheticPublicQuoteAndArtworkRetryUseOneSavedEnquiry()throws Exception{
  String key="batch5-e1-"+UUID.randomUUID(),email="batch5-e1-"+UUID.randomUUID()+"@example.test";
   Map<String,Object> payload=new LinkedHashMap<>();payload.put("customerName","Synthetic E1 quotation request");payload.put("email",email);payload.put("phone","+919000000129");payload.put("productCode","WEDDING_CARDS");payload.put("quantity",250);payload.put("privacyConsent",true);payload.put("privacyVersion",com.printflow.identity.CustomerIdentityController.PRIVACY);payload.put("website","");payload.put("intendedUse","Synthetic E1 wedding invitation quote");payload.put("whatsappConsent",true);
   Client client=new Client();String body=json.writeValueAsString(payload);var created=client.sendWithHeader("POST","/api/public/enquiries",body,"Idempotency-Key",key);assertEquals(201,created.statusCode(),created.body());var link=json.readValue(created.body(),com.printflow.enquiry.EnquiryDtos.CreatedEnquiry.class);UUID enquiry=jdbc.queryForObject("select id from enquiries where public_id=?",UUID.class,link.publicId());
   var replay=client.sendWithHeader("POST","/api/public/enquiries",body,"Idempotency-Key",key);assertEquals(201,replay.statusCode());var replayLink=json.readValue(replay.body(),com.printflow.enquiry.EnquiryDtos.CreatedEnquiry.class);assertEquals(link.publicId(),replayLink.publicId());assertEquals(link.trackingToken(),replayLink.trackingToken());
   assertEquals(1,jdbc.queryForObject("select count(*) from enquiries where public_id=?",Integer.class,link.publicId()));assertEquals(1,jdbc.queryForObject("select count(*) from whatsapp_contact_consents where enquiry_id=? and channel='WEBSITE' and granted=true",Integer.class,enquiry));
   byte[] png=com.printflow.files.ArtworkSamples.png("WEDDING_CARDS");
   assertEquals(400,uploadArtwork(client,link,"synthetic-retry.txt",png).statusCode(),"Invalid attachment is rejected while the saved enquiry remains available");
   assertEquals(0,jdbc.queryForObject("select count(*) from design_artifacts where enquiry_id=?",Integer.class,enquiry));
   var attached=uploadArtwork(client,link,"synthetic-retry.png",png);assertEquals(201,attached.statusCode(),attached.body());assertEquals(1,jdbc.queryForObject("select count(*) from design_artifacts where enquiry_id=?",Integer.class,enquiry));assertEquals("CLEAN",jdbc.queryForObject("select state from design_artifacts where enquiry_id=?",String.class,enquiry));
   assertEquals(1,jdbc.queryForObject("select count(*) from enquiries where public_id=?",Integer.class,link.publicId()),"Attachment retry must not create another enquiry");
 }

 private String syntheticPhone(){return "919"+String.format(java.util.Locale.ROOT,"%012d",Math.floorMod(UUID.randomUUID().getMostSignificantBits(),1_000_000_000_000L));}
 private int countMessages(UUID conversation,String direction){return jdbc.queryForObject("select count(*) from whatsapp_messages where conversation_id=? and direction=?",Integer.class,conversation,direction);}
 private byte[] webhookMessage(String id,String phone,String text)throws Exception{
  Map<String,Object> message=Map.of("id",id,"from",phone,"timestamp",Long.toString(Instant.now().getEpochSecond()),"type","text","text",Map.of("body",text));
  Map<String,Object> value=Map.of("messages",List.of(message));Map<String,Object> change=Map.of("value",value);
  return json.writeValueAsBytes(Map.of("entry",List.of(Map.of("changes",List.of(change)))));
 }
 private HttpResponse<String> webhookSignedMessage(String phone,String text)throws Exception{byte[] raw=webhookMessage("wamid.e1."+UUID.randomUUID(),phone,text);return webhook(raw,signature(raw));}
 private HttpResponse<String> webhookSignedStatus(String id,String status)throws Exception{
  Map<String,Object> event=Map.of("id",id,"status",status,"timestamp",Long.toString(Instant.now().getEpochSecond()));
  Map<String,Object> value=Map.of("statuses",List.of(event));Map<String,Object> change=Map.of("value",value);
  byte[] raw=json.writeValueAsBytes(Map.of("entry",List.of(Map.of("changes",List.of(change)))));
  return webhook(raw,signature(raw));
 }
 private HttpResponse<String> uploadArtwork(Client client,com.printflow.enquiry.EnquiryDtos.CreatedEnquiry link,String name,byte[] bytes)throws Exception{client.csrf();return client.client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/public/enquiries/"+link.publicId()+"/artwork")).timeout(Duration.ofSeconds(20)).header("X-CSRF-TOKEN",client.token).header("X-Tracking-Token",link.trackingToken()).header("X-File-Name",name).header("Content-Type","image/png").POST(HttpRequest.BodyPublishers.ofByteArray(bytes)).build(),HttpResponse.BodyHandlers.ofString());}
 private HttpResponse<String> webhook(byte[] raw,String signature)throws Exception{var builder=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/public/whatsapp/webhook")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(raw));if(signature!=null)builder.header("X-Hub-Signature-256",signature);var response=HttpClient.newHttpClient().send(builder.build(),HttpResponse.BodyHandlers.ofString());if(response.statusCode()>=500)throw new AssertionError("Synthetic webhook returned "+response.statusCode()+": "+response.body());return response;}
 private String signature(byte[] body)throws Exception{var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec("synthetic-batch5-webhook-secret".getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return "sha256="+java.util.HexFormat.of().formatHex(mac.doFinal(body));}
 @Test void ownerQueueRemovalIsArchivedAndNotifiedOnceIncludingGuests()throws Exception{UUID id=lead("NEW");String path="/api/v1/owner/enquiries/"+id+"/dismiss";assertEquals(403,artist.send("POST",path,"{\"revision\":0}",true).statusCode());assertEquals(200,boss.send("POST",path,"{\"revision\":0}",true).statusCode());assertEquals(200,boss.send("POST",path,"{\"revision\":0}",true).statusCode());assertEquals(1,jdbc.queryForObject("select count(*) from mail_outbox where enquiry_id=? and kind='REJECTION'",Integer.class,id));var notification=jdbc.queryForMap("select payload,state from mail_outbox where enquiry_id=?",id);assertEquals("PENDING",notification.get("state"));assertTrue(mail.decryptForDelivery(notification.get("payload").toString()).contains("phone"));assertFalse(notification.get("payload").toString().contains("scope@example.test"));assertEquals("REMOVED",jdbc.queryForObject("select closure_kind from enquiries where id=?",String.class,id));assertTrue(buyer.send("GET","/api/v1/customer/enquiries/"+id,null,false).body().contains("unable to fulfil"));assertFalse(boss.send("GET","/api/v1/staff/enquiries",null,false).body().contains(id.toString()));UUID guest=lead("NEW");jdbc.update("update enquiries set customer_user_id=null where id=?",guest);assertEquals(200,boss.send("POST","/api/v1/owner/enquiries/"+guest+"/dismiss","{\"revision\":0}",true).statusCode());assertNull(jdbc.queryForMap("select user_id from mail_outbox where enquiry_id=?",guest).get("user_id"));UUID accepted=lead("IN_PROGRESS");jdbc.update("insert into quote_versions(id,enquiry_id,version,scope,total_paise,terms,proposed_date,specification_snapshot,issued_by,state) values(?,?,1,'Scope',1000,'Terms',current_date+10,'{}'::jsonb,?,'ACCEPTED')",UUID.randomUUID(),accepted,owner);assertEquals(200,boss.send("POST","/api/v1/owner/enquiries/"+accepted+"/dismiss","{\"revision\":0}",true).statusCode());}
